html="""<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>百代鏡｜顔・髪・甲冑の着脱</title><style>*{box-sizing:border-box}body{margin:0;background:#1d2b33;color:#eee7db;font:16px/1.8 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:24px}h1{font-size:25px}h2{font-size:18px;color:#dfc18c}.row{display:flex;gap:30px;flex-wrap:wrap}.large{width:256px;height:384px;image-rendering:pixelated}.native{width:64px;height:96px;image-rendering:pixelated}canvas{background:repeating-conic-gradient(#bfc0b5 0 25%,#a5a99f 0 50%) 0/16px 16px}button,select{font:inherit;background:#344852;color:inherit;padding:6px 11px;border:1px solid #829397;margin:4px}label{margin-right:16px;display:inline-block}.note{border-left:3px solid #d7b57e;padding:10px 16px}.parts{display:flex;gap:30px;flex-wrap:wrap}a{color:#9ed7e6}</style><main><h1>顔・髪・甲冑の着脱｜64×96・1倍</h1><p>元絵と同じ座標のパーツを、変更していない仮素体へ重ねています。</p><div class="row"><section><h2>現在の組み合わせ・4倍</h2><canvas id="large" class="large" width="64" height="96"></canvas></section><section><h2>元の武将・4倍</h2><canvas id="source-large" class="large" width="64" height="96"></canvas></section><section><h2>パーツを表示</h2><label><input id="face" type="checkbox" checked>顔・髭</label><br><label><input id="hair" type="checkbox" checked>髪・落ち影</label><br><label><input id="armor" type="checkbox" checked>甲冑一式</label><p><button id="all">全部着ける</button><button id="none">全部外す</button></p><p><button id="hair-off">髪だけ外す</button><button id="armor-off">甲冑だけ外す</button></p><button data-bg="white">白</button><button data-bg="black">黒</button><button data-bg="checker">市松</button><p id="status">読み込み中…</p></section></div><h2>通常表示・1倍</h2><div class="row"><section><canvas id="native" class="native" width="64" height="96"></canvas><p>現在</p></section><section><canvas id="source-native" class="native" width="64" height="96"></canvas><p>元絵</p></section><section><canvas id="base-native" class="native" width="64" height="96"></canvas><p>元の素体</p></section></div><h2>独立パーツ・1倍</h2><div class="parts"><section><canvas id="face-part" class="native" width="64" height="96"></canvas><p>顔・髭</p></section><section><canvas id="hair-part" class="native" width="64" height="96"></canvas><p>髪・額の落ち影</p></section><section><canvas id="armor-part" class="native" width="64" height="96"></canvas><p>甲冑一式</p></section></div><p class="note">全パーツを着けた状態は元絵の可視画素と一致。全部外すと元の素体PNGに一致します。甲冑一式には下衣・陣羽織・籠手・脚具・履物・佩刀を含みます。今回はこの一式をひとつの装備として着脱します。</p><details><summary>素体を壊さず装備する仕組み</summary><p>素体の保存画素は変更しません。籠手・脚具・履物を着ける際は、装備側の遮蔽マスクが対応する手・すね・足の表示を隠します。外せばすべて元へ戻ります。元絵の輪郭で素体全体を切り抜く方法ではありません。</p><p>顔は、元絵の目眉・鼻・口・髭と、髪に隠れていた肌面で構成。髪の落ち影6画素は別の意味マスクで管理し、髪と一緒に外します。目眉を髪として分割していません。</p><p>素体の「細すぎて不自然」という課題は継続。正面静止のみで、別方向・歩行・別の髪型や甲冑への交換・6頭身素材との対応は未検証です。</p></details><p><a href="../../Art/Officer/EquipmentPartsV2/validation.json">実画素の検査</a> · <a href="officer-body-source-review.html">素体と元絵の重ね合わせ</a></p><script>"""
html+='const assets='+json.dumps(assets)+';'
html+="""const imgs={},selected=new Set(['face','hair','armor']);window.equipmentReady=false;let originalPixels,occlusionPixels;function draw(id,img){let c=document.getElementById(id).getContext('2d');c.clearRect(0,0,64,96);c.imageSmoothingEnabled=false;c.drawImage(img,0,0)}function render(){let c=document.getElementById('large').getContext('2d');c.clearRect(0,0,64,96);let image=new ImageData(new Uint8ClampedArray(originalPixels),64,96);if(selected.has('armor'))for(let i=0;i<image.data.length;i+=4)if(occlusionPixels[i]>0)image.data.fill(0,i,i+4);c.putImageData(image,0,0);for(let key of ['face','armor','hair'])if(selected.has(key))c.drawImage(imgs[key],0,0);draw('native',document.getElementById('large'));for(let key of ['face','hair','armor'])document.getElementById(key).checked=selected.has(key);document.getElementById('status').textContent=selected.size===3?'全装備：元絵と画素一致':selected.size===0?'全解除：元の素体と画素一致':'顔・髪・甲冑を独立して表示中'}function choose(keys){selected.clear();for(let k of keys)selected.add(k);render()}window.equipmentReview={choose,render};(async()=>{await Promise.all(Object.entries(assets).map(async([k,url])=>{let im=new Image;im.src=url;await im.decode();imgs[k]=im}));const tmp=document.createElement('canvas');tmp.width=64;tmp.height=96;let c=tmp.getContext('2d');c.drawImage(imgs.base,0,0);originalPixels=c.getImageData(0,0,64,96).data;c.clearRect(0,0,64,96);c.drawImage(imgs.occlusion,0,0);occlusionPixels=c.getImageData(0,0,64,96).data;draw('source-large',imgs.source);draw('source-native',imgs.source);draw('base-native',imgs.base);for(let k of ['face','hair','armor']){draw(k+'-part',imgs[k]);document.getElementById(k).onchange=e=>{e.target.checked?selected.add(k):selected.delete(k);render()}}document.getElementById('all').onclick=()=>choose(['face','hair','armor']);document.getElementById('none').onclick=()=>choose([]);document.getElementById('hair-off').onclick=()=>choose(['face','armor']);document.getElementById('armor-off').onclick=()=>choose(['face','hair']);document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>document.querySelectorAll('canvas').forEach(c=>c.style.background=b.dataset.bg==='checker'?'':b.dataset.bg==='white'?'white':'#10171c'));render();window.equipmentReady=true})().catch(e=>{document.getElementById('status').textContent=e.message;throw e});</script></main></html>"""
(r/'Docs/Proposals/officer-equipment-review.html').write_text(html,encoding='utf-8');print('EQUIPMENT_REVIEW_PAGE_READY')
